# Generated by Claude Fable 5 (Anthropic)
#!/usr/bin/env python3
"""join_analysis — measure a multi-input ("join") node from trace data.

A join node has several input callbacks (subscriptions) whose data is
combined inside the node (application memory: collectors / message_filters
sync policies / fusion buffers) and published by WHICHEVER callback completes
the set — or by a timeout timer. ROS-level tracing sees each input callback
run and sees the publish come out of ONE callback; the in-memory hand-off is
invisible. This script measures what CAN be measured, without heuristics
about the application's internals:

  1. Structure (always): the node's F callbacks split into inputs (sub),
     timeouts (tmr) and completers (F's that appear in fish_rclcpp_publish_link
     for the output topic). publish_link is deduped per (handle, callback), so
     it says WHO ever published, not how often.
  2. Per-instance (only if the session was traced with [trace] per_instance =
     true, i.e. ros2:rcl_publish / ros2:rcl_take in the whitelist):
       - completer distribution: for every rcl_publish on the output publisher,
         the callback whose callback_start/end window (same vtid, nesting-aware)
         contains it. Exact.
       - contribution per output: the input-callback arrivals (rcl_take inside an
         input F) since the previous output publish. Approximate — the trace has
         no collector/frame id and no stamps; overlapping frames blur it.

Usage:
  python3 postprocess/join_analysis.py <session_id> <node_label> [--topic /out/topic]
      [--scope __main__] [--json]
Example:
  python3 postprocess/join_analysis.py fish_20260817_094147 concatenate_data \\
      --topic /sensing/lidar/concatenated/pointcloud
"""
import argparse, bisect, collections, json, sys
import psycopg2

DSN = "host=localhost dbname=fish user=fish password=fish"


def load_node_fs(cur, sid, scope, node_label):
    cur.execute("""
      SELECT f.cb_addr, f.attrs, e.etype, e.label, n.label, n.full_name
      FROM graph_nodes f
      JOIN graph_edges g1 ON g1.session_id=f.session_id AND g1.scope=f.scope AND g1.target=f.node_id AND g1.rel='contains'
      JOIN graph_nodes e  ON e.session_id=g1.session_id AND e.scope=g1.scope AND e.node_id=g1.source AND e.type='E'
      JOIN graph_edges g2 ON g2.session_id=e.session_id AND g2.scope=e.scope AND g2.target=e.node_id AND g2.rel='contains'
      JOIN graph_nodes n  ON n.session_id=g2.session_id AND n.scope=g2.scope AND n.node_id=g2.source AND n.type='N'
      WHERE f.session_id=%s AND f.scope=%s AND f.type='F'
        AND (n.label=%s OR n.full_name=%s)
    """, (sid, scope, node_label, node_label))
    fs = {}
    for cb, attrs, etype, elabel, nlabel, nfull in cur.fetchall():
        attrs = attrs or {}
        entry = {"cb": cb, "etype": etype, "entity": elabel, "node": nfull or nlabel,
                 "aliases": set([cb])}
        ipw = attrs.get("ipc_waitable")
        if ipw:
            entry["aliases"].add(ipw)
        for a in attrs.get("alt_cb_addrs") or []:
            entry["aliases"].add(a)
        fs[cb] = entry
    return fs


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("session_id"); ap.add_argument("node_label")
    ap.add_argument("--topic", default=None, help="output topic (default: every topic the node publishes)")
    ap.add_argument("--scope", default="__main__")
    ap.add_argument("--json", action="store_true")
    a = ap.parse_args()
    S = a.session_id
    conn = psycopg2.connect(DSN); cur = conn.cursor()

    fs = load_node_fs(cur, S, a.scope, a.node_label)
    if not fs:
        sys.exit(f"no F callbacks found for node {a.node_label!r} in {S}")
    alias2cb = {al: cb for cb, e in fs.items() for al in e["aliases"]}
    label = lambda cb: (f"{fs[cb]['etype']}:{fs[cb]['entity']}" if cb in fs else cb)

    # node's vpid + publishers
    cur.execute("""SELECT n.vpid, n.payload->>'node_handle' FROM ros2_trace n
                   WHERE n.session_id=%s AND n.event='ros2:rcl_node_init'
                     AND (n.payload->>'node_name'=%s OR (n.payload->>'namespace')||'/'||(n.payload->>'node_name')=%s)""",
                (S, a.node_label.rsplit('/', 1)[-1], a.node_label))
    rows = cur.fetchall()
    if not rows:
        sys.exit("node not found in ros2_trace rcl_node_init")
    vpid, nh = rows[0]
    cur.execute("""SELECT payload->>'publisher_handle', payload->>'topic_name' FROM ros2_trace
                   WHERE session_id=%s AND event='ros2:rcl_publisher_init' AND vpid=%s AND payload->>'node_handle'=%s""",
                (S, vpid, nh))
    pubs = {h: t for h, t in cur.fetchall()}
    if a.topic:
        pubs = {h: t for h, t in pubs.items() if t == a.topic}
    if not pubs:
        sys.exit("no matching publisher on that node")

    # 1) structure from publish_link
    cur.execute("""SELECT payload->>'publisher_handle', payload->>'callback', count(*) FROM ros2_trace
                   WHERE session_id=%s AND event='ros2:fish_rclcpp_publish_link' AND payload->>'publisher_handle'=ANY(%s)
                   GROUP BY 1,2""", (S, list(pubs)))
    completers = collections.defaultdict(dict)
    for h, cb, n in cur.fetchall():
        completers[pubs[h]][alias2cb.get(cb, cb)] = n
    # data inputs vs infra/aux subs (/clock, /parameter_events, ...): reuse the
    # FT topic classifier so both views agree on what counts as plumbing.
    try:
        from postprocess.fish_viz_server import topic_class
    except Exception:
        def topic_class(t):
            return 'infra' if t in ('/clock', '/parameter_events', '/tf', '/tf_static', '/rosout') else 'data'
    inputs = [cb for cb, e in fs.items() if e["etype"] == "sub" and topic_class(e["entity"]) == "data"]
    aux    = [cb for cb, e in fs.items() if e["etype"] == "sub" and topic_class(e["entity"]) != "data"]
    timers = [cb for cb, e in fs.items() if e["etype"] == "tmr"]

    out = {"session": S, "node": a.node_label, "vpid": vpid,
           "inputs": [label(c) for c in inputs], "aux_inputs": [label(c) for c in aux],
           "timeouts": [label(c) for c in timers],
           "outputs": {}}

    # 2) per-instance if available
    cur.execute("SELECT count(*) FROM ros2_trace WHERE session_id=%s AND event='ros2:rcl_publish' AND vpid=%s", (S, vpid))
    n_rcl_pub = cur.fetchone()[0]
    per_instance = n_rcl_pub > 0

    # callback windows in this process (nesting-aware), for all node F aliases
    aliases = list(alias2cb)
    cur.execute("""SELECT vtid, ts_ns, event, payload->>'callback' FROM ros2_trace
                   WHERE session_id=%s AND vpid=%s AND event IN ('ros2:callback_start','ros2:callback_end')
                     AND payload->>'callback'=ANY(%s) ORDER BY vtid, ts_ns""", (S, vpid, aliases))
    wins = collections.defaultdict(list); stack = collections.defaultdict(list)
    for vtid, ts, ev, cb in cur.fetchall():
        if ev.endswith("start"):
            stack[vtid].append((ts, cb))
        elif stack[vtid]:
            t0, cb0 = stack[vtid].pop(); wins[vtid].append((t0, ts, alias2cb.get(cb0, cb0)))
    for v in wins: wins[v].sort()
    starts = {v: [w[0] for w in ws] for v, ws in wins.items()}

    def owner(vtid, ts):
        ws = wins.get(vtid)
        if not ws: return None
        i = bisect.bisect_right(starts[vtid], ts) - 1
        for j in range(i, max(-1, i - 8), -1):
            t0, t1, cb = ws[j]
            if t0 <= ts <= t1: return cb   # innermost among enclosing (later start wins)
        return None

    for h, topic in pubs.items():
        rec = {"ever_published_by": {label(cb): n for cb, n in completers.get(topic, {}).items()},
               "note_publish_link": "publish_link is deduped per (handle,callback,thread): counts are NOT publish frequencies"}
        if per_instance:
            cur.execute("""SELECT vtid, ts_ns FROM ros2_trace WHERE session_id=%s AND event='ros2:rcl_publish'
                           AND vpid=%s AND payload->>'publisher_handle'=%s ORDER BY ts_ns""", (S, vpid, h))
            pubs_i = cur.fetchall()
            dist = collections.Counter(); unk = 0
            for vtid, ts in pubs_i:
                o = owner(vtid, ts)
                if o: dist[label(o)] += 1
                else: unk += 1
            rec["n_publishes"] = len(pubs_i)
            rec["completer_distribution"] = dict(dist.most_common())
            rec["completer_unattributed"] = unk
            # Execution time by ROLE: the same input callback costs ~µs when it
            # only deposits its message and ~ms when it completes the set
            # (merge + publish run inside it). Split each callback's windows by
            # whether an output publish happened inside the window.
            pub_by_vt = collections.defaultdict(list)
            for vtid, ts in pubs_i: pub_by_vt[vtid].append(ts)
            for vt in pub_by_vt: pub_by_vt[vt].sort()
            def _pub_in(vt, t0, t1):
                l = pub_by_vt.get(vt, []); i = bisect.bisect_left(l, t0)
                return i < len(l) and l[i] <= t1
            role_dur = collections.defaultdict(list)
            for vt, ws in wins.items():
                for t0, t1, cb in ws:
                    if cb in fs:
                        role_dur[(label(cb), 'completer' if _pub_in(vt, t0, t1) else 'deposit_only')].append((t1 - t0) / 1e6)
            def _q(d, p): d = sorted(d); return d[int(p * (len(d) - 1))]
            rec["exec_ms_by_role"] = {f"{k[0]} | {k[1]}": {"n": len(d), "p50": round(_q(d, .5), 3), "p90": round(_q(d, .9), 3), "max": round(max(d), 3)}
                                      for k, d in sorted(role_dur.items()) if k[0] in [label(c) for c in inputs + timers]}
            # contributions: rcl_take is called by the executor BEFORE the callback
            # (take → dispatch), i.e. just outside the callback window on the same
            # thread. Attribute each take to the next callback_start on its vtid
            # (within 5 ms) — that callback consumed the taken message.
            cur.execute("""SELECT vtid, ts_ns FROM ros2_trace WHERE session_id=%s AND event='ros2:rcl_take' AND vpid=%s ORDER BY ts_ns""", (S, vpid))
            takes = []
            input_set = set(inputs)
            for vtid, ts in cur.fetchall():
                ws = wins.get(vtid)
                if not ws: continue
                i = bisect.bisect_left(starts[vtid], ts)
                if i < len(ws) and ws[i][0] - ts <= 5_000_000 and ws[i][2] in input_set:
                    takes.append((ts, ws[i][2]))
            rec["n_input_takes"] = len(takes)
            rec["takes_per_input"] = dict(collections.Counter(label(o) for _, o in takes))
            # AND-join test: for each output completed by an INPUT callback,
            # did every join member deliver within one member period before
            # the publish? Timer completions are expected to be incomplete
            # (timeout path). This is evidence, not proof: without a frame /
            # collector id (stamps are not traced) a jittered arrival slightly
            # older than one period can still belong to the frame — exact
            # per-instance proof needs collector identity (uprobe on the app's
            # collector methods, see notes).
            members = [cb for cb in inputs if fs[cb]["entity"] in
                       {fs[c]["entity"] for c in inputs}]  # all data inputs (caller may narrow via --topic later)
            arr = collections.defaultdict(list)
            for ts_, o in takes: arr[o].append(ts_)
            for o in arr: arr[o].sort()
            # member period ≈ median inter-arrival of the least frequent input
            per = None
            for o, aa in arr.items():
                if len(aa) > 5:
                    d = sorted(aa[i+1]-aa[i] for i in range(len(aa)-1)); m = d[len(d)//2]
                    per = m if per is None else max(per, m)
            win = (per or 200e6) * 1.0
            # only inputs that are actual join members: those with the same msg
            # type as completers is model-side; here use inputs that ever
            # completed + inputs whose take rate is within 2x of them
            comp_inputs = {alias2cb.get(cb, cb) for cb in completers.get(topic, {})} & set(inputs)
            rates = {o: len(aa) for o, aa in arr.items()}
            ref = min((rates[o] for o in comp_inputs if o in rates), default=None)
            join_members = [o for o in arr if ref and rates[o] <= 2 * ref] if ref else list(arr)
            andres = collections.Counter(); missing = collections.Counter()
            for vt, ts in pubs_i:
                o = owner(vt, ts); kind = ('timeout' if (o and fs.get(o, {}).get('etype') == 'tmr') else 'input')
                got = set()
                for m in join_members:
                    aa = arr[m]; i = bisect.bisect_left(aa, ts)
                    if i > 0 and ts - aa[i-1] <= win: got.add(m)
                ok = set(join_members) <= got
                andres[(kind, 'complete' if ok else 'incomplete')] += 1
                if not ok: missing[(kind, tuple(sorted(label(m) for m in set(join_members) - got)))] += 1
            # --- automatic classification (see notes/join_semantics_from_traces.txt) ---
            n_out = len(pubs_i)
            comp_inputs_lbl = {label(alias2cb.get(cb, cb)) for cb in completers.get(topic, {}) if alias2cb.get(cb, cb) in inputs}
            comp_timers = {label(alias2cb.get(cb, cb)) for cb in completers.get(topic, {}) if fs.get(alias2cb.get(cb, cb), {}).get('etype') == 'tmr'}
            n_timer_out = sum(v for (k, kind), v in andres.items() if k == 'timeout') if False else sum(v for k, v in andres.items() if k[0] == 'timeout')
            n_input_out = n_out - n_timer_out
            sum_inputs = sum(len(arr[m]) for m in join_members) or 1
            min_inputs = min((len(arr[m]) for m in join_members), default=0)
            # bimodality: an input callback with both cheap and heavy executions
            bimodal = [k for k, v in rec["exec_ms_by_role"].items() if k.endswith('| completer') and v['p50'] > 5 * max(0.001, rec["exec_ms_by_role"].get(k.replace('| completer', '| deposit_only'), {'p50': 0.001})['p50'])]
            deposit_only_present = any(k.endswith('| deposit_only') and v['n'] > 0 for k, v in rec["exec_ms_by_role"].items())
            timer_all_incomplete = (n_timer_out > 0 and andres.get(('timeout', 'complete'), 0) == 0)
            if n_input_out == 0 and n_timer_out > 0:
                cls = "1b timer-driven"; why = "all outputs come from a timer callback; inputs only deposit"
            elif len(comp_inputs_lbl) >= 2 and deposit_only_present and n_out <= 1.5 * min_inputs and (n_timer_out == 0 or timer_all_incomplete):
                cls = "2 AND-join" + (" with timeout" if n_timer_out else ""); why = (f"{len(comp_inputs_lbl)} inputs complete outputs, deposit-only executions exist (bimodal), "
                       f"outputs {n_out} ≈ min input {min_inputs}" + (", every timer output incomplete" if n_timer_out else ""))
            elif n_out >= 0.8 * sum_inputs and not deposit_only_present:
                cls = "1a runs-on-every-message (any/OR)"; why = f"outputs {n_out} ≈ Σ inputs {sum_inputs}, no deposit-only executions"
            else:
                cls = "undetermined"; why = f"outputs {n_out}, Σ inputs {sum_inputs}, min {min_inputs}, completers {sorted(comp_inputs_lbl)}, timers {sorted(comp_timers)}"
            rec["classification"] = {"case": cls, "why": why}
            rec["and_join_test"] = {
                "members": [label(m) for m in join_members], "window_ms": round(win / 1e6, 1),
                "counts": {f"{k[0]}|{k[1]}": v for k, v in andres.items()},
                "missing": {f"{k[0]}|{','.join(k[1])}": v for k, v in missing.items()},
                "note": "evidence, not proof: no frame/collector id in the trace; timeout completions are expected incomplete",
            }
            pub_ts = [ts for _, ts in pubs_i]
            buckets = collections.defaultdict(collections.Counter)  # publish idx → input counts since previous publish
            for ts, o in takes:
                k = bisect.bisect_left(pub_ts, ts)      # index of the first publish AFTER this take
                buckets[k][label(o)] += 1
            shape = collections.Counter(tuple(sorted(c.items())) for k, c in buckets.items() if k < len(pub_ts))
            rec["contribution_sets_per_output"] = [{"inputs": dict(k), "n_outputs": v} for k, v in shape.most_common(8)]
            rec["note_contributions"] = ("approximate: takes are bucketed between consecutive output publishes; "
                                         "the trace carries no frame/collector id, overlapping frames blur this")
        else:
            rec["per_instance"] = "not traced ([trace] per_instance=false) — completer frequencies unknown"
        out["outputs"][topic] = rec

    if a.json:
        print(json.dumps(out, indent=2)); return
    print(f"JOIN ANALYSIS  session={S}  node={a.node_label} (vpid {vpid})")
    print(f"  data inputs ({len(inputs)}): " + ", ".join(out["inputs"]))
    print(f"  aux inputs ({len(aux)}):  " + ", ".join(out["aux_inputs"]))
    print(f"  timeouts ({len(timers)}): " + ", ".join(out["timeouts"]))
    for topic, rec in out["outputs"].items():
        print(f"\n  OUTPUT {topic}")
        print("    ever published by (publish_link, deduped): " + ", ".join(rec["ever_published_by"]) if rec["ever_published_by"] else "    (no publish_link)")
        if "completer_distribution" in rec:
            n = rec["n_publishes"]
            print(f"    per-instance completer distribution over {n} publishes:")
            for k, v in rec["completer_distribution"].items():
                print(f"       {v:>5} ({v/n*100:5.1f}%)  {k}")
            if rec["completer_unattributed"]:
                print(f"       {rec['completer_unattributed']:>5}  (publish outside any traced callback)")
            print(f"    input takes attributed: {rec['n_input_takes']}  {rec['takes_per_input']}")
            print("    execution time by role (ms) — completer = an output publish happened inside the window:")
            for k, v in rec["exec_ms_by_role"].items():
                print(f"       {k:<75} n={v['n']:>4}  p50={v['p50']:>8.3f}  p90={v['p90']:>8.3f}  max={v['max']:>8.3f}")
            print(f"    ==> classification: {rec['classification']['case']}  ({rec['classification']['why']})")
            aj = rec["and_join_test"]
            print(f"    AND-join test (members={aj['members']}, window={aj['window_ms']} ms):")
            for k, v in sorted(aj["counts"].items()): print(f"       {v:>4}  {k}")
            if aj["missing"]: print(f"       missing: {aj['missing']}")
            print("    contribution sets per output (approx., takes bucketed between consecutive publishes):")
            for c in rec["contribution_sets_per_output"]:
                print(f"       {c['n_outputs']:>4}×  {c['inputs']}")
        else:
            print("    " + rec["per_instance"])


if __name__ == "__main__":
    main()
